"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface IndicatorProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Wat er in het hoekje komt: een getal, een stip of een klein icoon. */
  badge?: React.ReactNode;
  /** Hoek waar het hoekje hangt. */
  placement?: "top-right" | "top-left" | "bottom-right" | "bottom-left";
  tone?: "red" | "accent" | "green" | "amber" | "blue" | "neutral";
  /** Alleen een stip, zonder inhoud. */
  dot?: boolean;
  /** Verbergt het hoekje, bijvoorbeeld bij nul meldingen. */
  hidden?: boolean;
  /** Getallen boven dit maximum worden als "99+" getoond. */
  max?: number;
  label?: string;
}

/**
 * Indicator — telbadge of stip op de hoek van iets anders: een knop, een
 * avatar, een tabblad.
 */
export const Indicator = React.forwardRef<HTMLSpanElement, IndicatorProps>(function Indicator(
  { badge, placement = "top-right", tone = "red", dot, hidden, max = 99, label, className, children, ...rest },
  ref
) {
  const inhoud =
    typeof badge === "number" && badge > max ? `${max}+` : badge;

  return (
    <span ref={ref} className={cn("lui-indicator", className)} {...rest}>
      {children}
      {!hidden && (
        <span
          className={cn(
            "lui-indicator-badge",
            `lui-indicator-${tone}`,
            `lui-indicator-${placement}`,
            (dot || inhoud === undefined) && "lui-indicator-dot"
          )}
          aria-label={label}
          role={label ? "status" : undefined}
          aria-hidden={label ? undefined : true}
        >
          {!dot && inhoud}
        </span>
      )}
    </span>
  );
});

/* ============================ Indicator ============================ */
.lui-indicator { position: relative; display: inline-flex; }

.lui-indicator-badge {
  position: absolute; z-index: 1;
  display: grid; place-items: center;
  min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: var(--r-full);
  border: 2px solid var(--surface);
  font-size: 10.5px; font-weight: 800; line-height: 1;
  font-variant-numeric: tabular-nums;
}
.lui-indicator-dot { min-width: 10px; width: 10px; height: 10px; padding: 0; }

.lui-indicator-top-right { top: 0; right: 0; translate: 40% -40%; }
.lui-indicator-top-left { top: 0; left: 0; translate: -40% -40%; }
.lui-indicator-bottom-right { bottom: 0; right: 0; translate: 40% 40%; }
.lui-indicator-bottom-left { bottom: 0; left: 0; translate: -40% 40%; }

.lui-indicator-red { background: var(--red); color: #fff; }
.lui-indicator-accent { background: var(--accent); color: var(--accent-fg); }
.lui-indicator-green { background: var(--green); color: #fff; }
.lui-indicator-amber { background: var(--amber); color: #fff; }
.lui-indicator-blue { background: var(--blue); color: #fff; }
.lui-indicator-neutral { background: var(--text-3); color: var(--surface); }
